// features/vendor-lifecycle.feature: "Once a vendor is sent back, its other documents cannot be decided"
import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

interface ExtractionRow {
  id: string;
  document_id: string;
  kind: "w9" | "insurance_certificate" | "contract";
  status: "pending_review" | "approved" | "rejected";
}

interface ReviewQueueRow {
  vendor_id: string;
  extractions: ExtractionRow[];
}

interface VendorBody {
  id: string;
  status: string;
}

interface DocumentBody {
  id: string;
  kind: string;
}

const PDF_BYTES = Buffer.from("%PDF-1.4\n% lifecycle test document\n%%EOF\n");

async function uploadDocument(member: APIRequestContext, vendorId: string, kind: "w9" | "contract") {
  const response = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind,
      file: { name: `${kind}-${Date.now()}.pdf`, mimeType: "application/pdf", buffer: PDF_BYTES },
    },
  });
  return expectStatus<DocumentBody>(response, 201);
}

/** Returns the vendor's extractions from the review queue once both kinds have appeared. */
async function queuedExtractionsFor(
  reviewer: APIRequestContext,
  vendorId: string,
): Promise<Partial<Record<"w9" | "contract", ExtractionRow>> | undefined> {
  const queue = await expectStatus<ReviewQueueRow[]>(await reviewer.get("/api/review-queue"), 200);
  const item = queue.find((row) => row.vendor_id === vendorId);
  if (!item) return undefined;
  const byKind: Partial<Record<"w9" | "contract", ExtractionRow>> = {};
  for (const extraction of item.extractions) {
    if (extraction.kind === "w9" || extraction.kind === "contract") {
      byKind[extraction.kind] = extraction;
    }
  }
  return byKind.w9 && byKind.contract ? byKind : undefined;
}

test(
  "once a vendor is sent back, its other documents cannot be decided",
  { tag: "@LIF-03" },
  async ({ apiAs }) => {
    // Arrange: a vendor in review, created and submitted by a member
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const uniqueSuffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

    const created = await expectStatus<VendorBody>(
      await member.post("/api/vendors", {
        data: {
          name: `Lifecycle Vendor ${uniqueSuffix}`,
          category: "services",
          contact_email: `lifecycle-${uniqueSuffix}@vendor.test`,
        },
      }),
      201,
    );

    await uploadDocument(member, created.id, "w9");
    await uploadDocument(member, created.id, "contract");

    const submitted = await expectStatus<VendorBody>(
      await member.post(`/api/vendors/${created.id}/submit`),
      200,
    );
    expect(submitted.status).toBe("in_review");

    let extractions: Partial<Record<"w9" | "contract", ExtractionRow>> | undefined;
    await expect
      .poll(async () => {
        extractions = await queuedExtractionsFor(reviewer, created.id);
        return extractions !== undefined;
      })
      .toBe(true);

    const w9 = extractions!.w9!;
    const contract = extractions!.contract!;

    // Arrange: reviewer sends the vendor back by rejecting the w9 extraction
    await expectStatus<{ status: string }>(
      await reviewer.post(`/api/extractions/${w9.id}/decision`, {
        data: { decision: "reject", note: "W-9 signature missing" },
      }),
      200,
    );

    // Act: reviewer tries to approve the contract extraction on the same vendor
    const response = await reviewer.post(`/api/extractions/${contract.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert
    const body = await expectStatus<{ error: { code: string } }>(response, 409);
    expect(body.error.code).toBe("vendor_not_in_review");
  },
);
